#include <string>
#include <queue>
#include <unordered_set>
#include <algorithm>
using namespace std;

class Solution {
public:
    string findLexSmallestString(string s, int a, int b) {
        unordered_set<string> seen;
        queue<string> q;
        q.push(s);
        seen.insert(s);
        string res = s;

        while (!q.empty()) {
            string cur = q.front(); q.pop();
            res = min(res, cur);

            // Add operation
            string t = cur;
            for (int i = 1; i < t.size(); i += 2)
                t[i] = (t[i] - '0' + a) % 10 + '0';

            if (!seen.count(t)) {
                seen.insert(t);
                q.push(t);
            }

            // Rotate operation
            t = cur.substr(cur.size() - b) + cur.substr(0, cur.size() - b);
            if (!seen.count(t)) {
                seen.insert(t);
                q.push(t);
            }
        }
        return res;
    }
};
